I'm setting up a simple donation vault smart contract for our nonprofit. I need you to handle the full setup process:

1. Create two Ethereum accounts — one as the admin and one as the operator.
2. Compile this Solidity vault contract:

```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract DonationVault {
    address public admin;

    constructor() {
        admin = msg.sender;
    }

    function donate() public payable {
        require(msg.value > 0, "Donation must be greater than zero");
    }

    function withdrawFunds(uint256 amount) public {
        require(msg.sender == admin, "Only admin can withdraw");
        payable(admin).transfer(amount);
    }

    function getBalance() public view returns (uint256) {
        return address(this).balance;
    }
}
```

3. Deploy the compiled contract to the network.
4. Before we start accepting donations, I want to know the estimated gas cost for calling the `donate` function on the deployed contract (use an empty argument string since it takes no parameters).
5. Sign a deployment attestation message "DONATION_VAULT_DEPLOYED_2026" using the admin account's private key, so we have a cryptographic record for our compliance audit.
6. Transfer 0.05 ether from the admin account to the operator account to cover initial operational gas costs.

Please complete all steps and report the results of each.

